const requiredNumber = value => {
    if (value === null || value === undefined || value === '' || !Number.isFinite(Number(value))) {
        throw new Error('Missing or invalid numeric observation');
    }
    return Number(value);
};
global.set('sensorData', {
    device: msg.payload.device || 'esp32-wokwi',
    temperature: requiredNumber(msg.payload.temperature),
    humidity: requiredNumber(msg.payload.humidity),
    smoke: requiredNumber(msg.payload.smoke),
    alert: msg.payload.alert || false,
    timestamp: new Date().toISOString()
});

node.status({fill:"green", shape:"dot", text:`${msg.payload.device}: Temp=${msg.payload.temperature}°C`});

return msg;

// Cria 3 mensagens, uma para cada estado
const states = [
    { city: "Manaus", state: "Amazonas", abbr: "AM", country: "Brazil" },
    { city: "Campo Grande", state: "Mato Grosso do Sul", abbr: "MS", country: "Brazil" },
    { city: "Belo Horizonte", state: "Minas Gerais", abbr: "MG", country: "Brazil" }
];

const messages = states.map(location => {
    return {
        payload: msg.payload,
        location: location
    };
});

return [messages];

// Rotear para o nó OpenWeather correto baseado na localização
const city = msg.location.city;

node.status({fill:"blue", shape:"ring", text:`Roteando ${city}...`});

// Retorna null para as saídas que não correspondem à cidade
// Saída 1: Manaus (AM)
// Saída 2: Campo Grande (MS)
// Saída 3: Belo Horizonte (MG)

if (city === "Manaus") {
    return [msg, null, null];
} else if (city === "Campo Grande") {
    return [null, msg, null];
} else if (city === "Belo Horizonte") {
    return [null, null, msg];
}

// Fallback: se não reconhecer a cidade, não envia para nenhum
node.error(`Cidade desconhecida: ${city}`);
return [null, null, null];

const requiredNumber = value => {
    if (value === null || value === undefined || value === '' || !Number.isFinite(Number(value))) {
        throw new Error('Missing or invalid numeric observation');
    }
    return Number(value);
};
const sensor = global.get('sensorData');
if (!sensor) throw new Error('Sensor data is required before scoring');

const weather = msg.payload;
const extTemp = requiredNumber(weather.tempc);
const extHumidity = requiredNumber(weather.humidity);
const windSpeed = requiredNumber(weather.windspeed);
const conditions = weather.description || 'desconhecido';

let location;
if (msg.location && msg.location.abbr) {
    location = msg.location;
} else {
    const cityName = weather.location || '';
    if (cityName.includes('Manaus')) {
        location = { city: 'Manaus', state: 'Amazonas', abbr: 'AM', country: 'Brazil' };
    } else if (cityName.includes('Campo Grande')) {
        location = { city: 'Campo Grande', state: 'Mato Grosso do Sul', abbr: 'MS', country: 'Brazil' };
    } else if (cityName.includes('Belo Horizonte')) {
        location = { city: 'Belo Horizonte', state: 'Minas Gerais', abbr: 'MG', country: 'Brazil' };
    } else {
        node.warn(`⚠️ Localização não encontrada! weather.location=${cityName}`);
        location = { city: cityName || 'Desconhecido', state: 'N/A', abbr: 'XX', country: 'Brazil' };
    }
}

let riskScore = 0;
let riskLevel = 'BAIXO';
let riskColor = '🟢';

if (sensor.smoke > 600) riskScore += 40;
else if (sensor.smoke > 400) riskScore += 30;
else if (sensor.smoke > 200) riskScore += 15;

if (sensor.temperature > 50) riskScore += 25;
else if (sensor.temperature > 40) riskScore += 20;
else if (sensor.temperature > 35) riskScore += 10;

if (extTemp > 35) riskScore += 15;
else if (extTemp > 30) riskScore += 10;
else if (extTemp > 25) riskScore += 5;

const avgHumidity = (sensor.humidity + extHumidity) / 2;
if (avgHumidity < 30) riskScore += 10;
else if (avgHumidity < 50) riskScore += 5;

if (windSpeed > 40) riskScore += 10;
else if (windSpeed > 20) riskScore += 5;

if (riskScore >= 70) {
    riskLevel = 'CRÍTICO';
    riskColor = '🔴';
} else if (riskScore >= 50) {
    riskLevel = 'ALTO';
    riskColor = '🟠';
} else if (riskScore >= 30) {
    riskLevel = 'MÉDIO';
    riskColor = '🟡';
} else {
    riskLevel = 'BAIXO';
    riskColor = '🟢';
}

const timestamp = new Date();

msg.payload = {
    sensor: {
        device: sensor.device,
        temperature: sensor.temperature,
        humidity: sensor.humidity,
        smoke: sensor.smoke
    },
    weather: {
        temperature: extTemp,
        humidity: extHumidity,
        windSpeed: windSpeed,
        conditions: conditions
    },
    location: location,
    risk: {
        score: riskScore,
        level: riskLevel,
        color: riskColor,
        shouldAlert: riskScore >= 50
    },
    timestamp: timestamp.toISOString()
};

node.status({
    fill: riskScore >= 70 ? "red" : riskScore >= 50 ? "yellow" : "green",
    shape: "dot",
    text: `${sensor.device}/${location.abbr}: ${riskLevel} (${riskScore})`
});

if (msg.payload.risk.shouldAlert) {
    return [msg, msg];
} else {
    return [msg, null];
}

// node-red-contrib-influxdb expects [fields, tags] for a tagged point.
const data = msg.payload;
const numeric = value => {
    const number = Number(value);
    if (!Number.isFinite(number)) throw new Error("Non-finite measurement");
    return number;
};
const timestamp = new Date(data.timestamp);
if (!Number.isFinite(timestamp.getTime())) throw new Error("Invalid timestamp");
msg.payload = [{
    sensor_temp: numeric(data.sensor.temperature),
    sensor_humidity: numeric(data.sensor.humidity),
    sensor_smoke: numeric(data.sensor.smoke),
    weather_temp: numeric(data.weather.temperature),
    weather_humidity: numeric(data.weather.humidity),
    weather_wind: numeric(data.weather.windSpeed),
    risk_score: numeric(data.risk.score),
    time: timestamp
}, {
    device: String(data.sensor.device || 'unknown'),
    location: String(data.location.city || 'unknown'),
    state: String(data.location.abbr || 'XX'),
    region: String(data.location.state || 'unknown'),
    risk_level: String(data.risk.level),
    alert: String(Boolean(data.risk.shouldAlert))
}];
msg.measurement = 'fire_detection';
return msg;

const data = msg.payload;
const risk = data.risk;
const sensor = data.sensor;
const weather = data.weather;
const location = data.location;

const message = 
    `${risk.color} *ALERTA DE RISCO DE QUEIMADA: ${risk.level}* ${risk.color}\n\n` +
    `🔥 *PONTUAÇÃO DE RISCO: ${risk.score}/100*\n\n` +
    `━━━━━━━━━━━━━━━━━━━━\n` +
    `📍 *LOCALIZAÇÃO*\n` +
    `🏙️ Cidade: ${location.city}\n` +
    `🗺️ Estado: ${location.state} (${location.abbr})\n\n` +
    `━━━━━━━━━━━━━━━━━━━━\n` +
    `📊 *DADOS DO SENSOR IoT*\n` +
    `🌡️ Temperatura: ${sensor.temperature.toFixed(1)}°C\n` +
    `💧 Umidade: ${sensor.humidity.toFixed(1)}%\n` +
    `💨 Fumaça: ${sensor.smoke.toFixed(0)} ppm\n` +
    `🤖 Dispositivo: ${sensor.device}\n\n` +
    `━━━━━━━━━━━━━━━━━━━━\n` +
    `🌦️ *CONDIÇÕES METEOROLÓGICAS REAIS*\n` +
    `🌡️ Temperatura: ${weather.temperature.toFixed(1)}°C\n` +
    `💧 Umidade: ${weather.humidity.toFixed(1)}%\n` +
    `💨 Vento: ${weather.windSpeed.toFixed(1)} km/h\n` +
    `☁️ Condições: ${weather.conditions}\n\n` +
    `━━━━━━━━━━━━━━━━━━━━\n` +
    `⏰ ${new Date().toLocaleString('pt-BR', {timeZone: 'America/Sao_Paulo'})}\n\n`;

if (risk.level === 'CRÍTICO') {
    msg.payload = message + `🚨 *AÇÃO IMEDIATA NECESSÁRIA!*\n⚠️ Risco extremo de queimada detectado!\n🚒 Acione os bombeiros: 193`;
} else if (risk.level === 'ALTO') {
    msg.payload = message + `⚠️ *Atenção redobrada necessária!*\n📞 Mantenha contato com autoridades locais`;
} else {
    msg.payload = message + `⚠️ *Monitoramento contínuo recomendado*`;
}

node.status({
    fill: "green",
    shape: "dot",
    text: `Enviando alerta ${location.abbr}`
});

return msg;

// Limpar dados antigos do sensor
global.set('sensorData', null);

node.status({fill:"green", shape:"ring", text:"Cache limpo!"});
node.warn("✅ Cache de sensorData limpo com sucesso!");

return null;

// Simulador automático que gera dados variados para os dashboards
// Alterna entre diferentes cenários de risco de forma realista

// Obter contador do contexto (para variar os cenários)
let counter = context.get('counter') || 0;
counter++;
context.set('counter', counter);

// Definir cenário baseado no contador (ciclo de 12 execuções = 6 minutos)
let scenario = counter % 12;

let temperature, humidity, smoke, alert, device;

// Alternar entre dispositivos
device = (counter % 2 === 0) ? "esp32-wokwi" : "api";

// Cenários variados (ciclo completo a cada 6 minutos)
if (scenario < 3) {
    // Cenário 1-3: BAIXO - Condições normais (25%)
    temperature = 22 + Math.random() * 8; // 22-30°C
    humidity = 55 + Math.random() * 20;   // 55-75%
    smoke = 80 + Math.random() * 100;     // 80-180 ppm
    alert = false;
} else if (scenario < 5) {
    // Cenário 4-5: MÉDIO - Condições de atenção (17%)
    temperature = 30 + Math.random() * 8; // 30-38°C
    humidity = 35 + Math.random() * 20;   // 35-55%
    smoke = 200 + Math.random() * 150;    // 200-350 ppm
    alert = false;
} else if (scenario < 8) {
    // Cenário 6-8: ALTO - Situação preocupante (25%)
    temperature = 38 + Math.random() * 10; // 38-48°C
    humidity = 20 + Math.random() * 20;    // 20-40%
    smoke = 400 + Math.random() * 200;     // 400-600 ppm
    alert = true;
} else if (scenario < 10) {
    // Cenário 9-10: CRÍTICO - Emergência (17%)
    temperature = 48 + Math.random() * 12; // 48-60°C
    humidity = 10 + Math.random() * 15;    // 10-25%
    smoke = 600 + Math.random() * 300;     // 600-900 ppm
    alert = true;
} else {
    // Cenário 11-12: Retorno ao BAIXO (16%)
    temperature = 24 + Math.random() * 6; // 24-30°C
    humidity = 60 + Math.random() * 15;   // 60-75%
    smoke = 90 + Math.random() * 80;      // 90-170 ppm
    alert = false;
}

// Arredondar valores
temperature = Math.round(temperature * 10) / 10;
humidity = Math.round(humidity * 10) / 10;
smoke = Math.round(smoke);

// Adicionar pequenas variações para realismo
const variation = (Math.random() - 0.5) * 2;
temperature += variation;
humidity += variation;

// Garantir limites
temperature = Math.max(15, Math.min(65, temperature));
humidity = Math.max(10, Math.min(95, humidity));
smoke = Math.max(50, Math.min(1000, smoke));

// Criar payload
msg.payload = {
    device: device,
    temperature: Math.round(temperature * 10) / 10,
    humidity: Math.round(humidity * 10) / 10,
    smoke: smoke,
    alert: alert
};

// Status visual
let riskLevel = "BAIXO";
if (smoke > 600 || temperature > 50) riskLevel = "CRÍTICO";
else if (smoke > 400 || temperature > 40) riskLevel = "ALTO";
else if (smoke > 200 || temperature > 32) riskLevel = "MÉDIO";

node.status({
    fill: riskLevel === "CRÍTICO" ? "red" : riskLevel === "ALTO" ? "orange" : riskLevel === "MÉDIO" ? "yellow" : "green",
    shape: "dot",
    text: `${device}: ${riskLevel} | T:${temperature.toFixed(1)}°C S:${smoke}ppm`
});

return msg;

